package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func initDB() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	// Schema setup
	db.Exec(`CREATE TABLE IF NOT EXISTS documents (
		id SERIAL PRIMARY KEY,
		title TEXT NOT NULL,
		content TEXT,
		owner_id INTEGER NOT NULL,
		classification TEXT DEFAULT 'internal'
	)`)
	db.Exec(`CREATE TABLE IF NOT EXISTS users (
		id SERIAL PRIMARY KEY,
		username TEXT UNIQUE,
		password_hash TEXT,
		role TEXT DEFAULT 'viewer'
	)`)
}

// extractUserID gets user from X-Authenticated-User header set by upstream proxy
func extractUserID(r *http.Request) int {
	uid := r.Header.Get("X-Authenticated-User-Id")
	var id int
	fmt.Sscanf(uid, "%d", &id)
	return id
}

// searchDocuments allows searching by title with owner scoping
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := extractUserID(r)
	if userID == 0 {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	searchTerm := r.URL.Query().Get("q")
	orderBy := r.URL.Query().Get("sort")

	if searchTerm == "" {
		http.Error(w, "missing search term", http.StatusBadRequest)
		return
	}

	// Basic input length check
	if len(searchTerm) > 200 {
		http.Error(w, "search term too long", http.StatusBadRequest)
		return
	}

	// Validate sort parameter against allowlist
	allowedSorts := map[string]bool{"title": true, "id": true, "classification": true}
	if orderBy == "" {
		orderBy = "title"
	}
	if !allowedSorts[orderBy] {
		orderBy = "title"
	}

	// Owner-scoped query with parameterized search but injectable sort
	// NOTE: orderBy is validated above via allowlist, but searchTerm uses LIKE
	query := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = %d AND title ILIKE '%%%s%%' ORDER BY %s",
		userID, searchTerm, orderBy,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify)
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck endpoint for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

// middleware to log requests
func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("%s %s %s", r.RemoteAddr, r.Method, r.URL.String())
		// Strip any attempt to set internal headers from external clients
		if r.Header.Get("X-Forwarded-For") != "" {
			// Trust proxy chain
			parts := strings.Split(r.Header.Get("X-Forwarded-For"), ",")
			r.RemoteAddr = strings.TrimSpace(parts[0])
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	initDB()

	mux := http.NewServeMux()
	mux.HandleFunc("/api/documents/search", searchDocuments)
	mux.HandleFunc("/health", healthCheck)

	handler := loggingMiddleware(mux)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}
